-- VERIFICACIÓN POSTERIOR de NEX-070. SOLO LECTURA. Cada fila debe dar ok = true. La ejecuta el responsable en la VM INMEDIATAMENTE después de aplicar la migración:
--   docker exec -i nexit-db psql -U nexit_app -d nexit -v ON_ERROR_STOP=1 < verificar-NEX-070.sql
BEGIN READ ONLY;
SELECT 'tabla nce_descuentos existe y está vacía al aplicar' AS control, to_regclass('public.nce_descuentos') IS NOT NULL AND (SELECT count(*) FROM public.nce_descuentos) = 0 AS ok
UNION ALL SELECT 'PK (empresa, nce) y FK compuesta a nce_origen (empresa, nce, fe)', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.nce_descuentos'::regclass AND contype = 'p') AND EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.nce_descuentos'::regclass AND contype = 'f' AND confrelid = 'public.nce_origen'::regclass)
UNION ALL SELECT 'tabla de solo altas (disparadores de fila y TRUNCATE)', (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'public.nce_descuentos'::regclass AND NOT tgisinternal AND tgname LIKE 'nce_descuentos_inmutable%') = 2
UNION ALL SELECT 'fe_documento_crear_nce sigue con la misma firma, SECURITY DEFINER y search_path fijo', EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = 'public.fe_documento_crear_nce(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb)'::regprocedure AND p.prosecdef AND p.proconfig::text LIKE '%search_path%')
UNION ALL SELECT 'la función conoce el servicio DESCUENTO y el saldo global', (SELECT prosrc FROM pg_proc WHERE oid = 'public.fe_documento_crear_nce(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb)'::regprocedure) LIKE '%nce_descuentos%' AND (SELECT prosrc FROM pg_proc WHERE oid = 'public.fe_documento_crear_nce(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb)'::regprocedure) LIKE '%v_usado_glob%'
UNION ALL SELECT 'el rol de la aplicación LEE nce_descuentos pero no la escribe, y ejecuta la creación de NCE', has_table_privilege('nexit_runtime', 'public.nce_descuentos', 'SELECT') AND NOT (has_table_privilege('nexit_runtime', 'public.nce_descuentos', 'INSERT') OR has_table_privilege('nexit_runtime', 'public.nce_descuentos', 'UPDATE') OR has_table_privilege('nexit_runtime', 'public.nce_descuentos', 'DELETE')) AND has_function_privilege('nexit_runtime', 'public.fe_documento_crear_nce(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb)', 'EXECUTE')
UNION ALL SELECT 'PUBLIC no ejecuta fe_documento_crear_nce', NOT EXISTS (SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE p.oid = 'public.fe_documento_crear_nce(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb)'::regprocedure AND a.grantee = 0);
ROLLBACK;
